cp lib/data.ts /tmp/data.ts.bak && cat > lib/data.ts <<'EOF'
import { connection } from 'next/server'

export async function getInventory() {
  await connection()
  await new Promise((r) => setTimeout(r, 3000))
  return {
    count: Math.floor(Math.random() * 50),
    price: (Math.random() * 100).toFixed(2),
  }
}
EOF
npm run build >/dev/null 2>&1 && echo "build ok"

cat > /tmp/probe.mjs <<'EOF'
const t0 = Date.now()
const res = await fetch('http://localhost:3111/product')
let buf = ''
const marks = {}
for await (const chunk of res.body) {
  buf += Buffer.from(chunk).toString()
  const el = ((Date.now() - t0) / 1000).toFixed(3)
  if (!marks.title && buf.includes('Premium Widget')) marks.title = el
  if (!marks.fallback && buf.includes('Loading inventory')) marks.fallback = el
  if (!marks.data && buf.includes('in stock')) marks.data = el
}
console.log(`TTFB->title    : ${marks.title}s`)
console.log(`fallback       : ${marks.fallback}s`)
console.log(`inventory data : ${marks.data}s`)
console.log(`total          : ${((Date.now()-t0)/1000).toFixed(3)}s`)
EOF
node /tmp/probe.mjs

cp app/product/page.tsx /tmp/page.fixed.tsx && cat > app/product/page.tsx <<'EOF'
